 * input of a session; the rules read it and never change it
 * (docs/design/BUILD-CONTRACT.md § 5.1, rule K-4).
 */
data class PhomuGameConfig (
    /**
     * The identifiers of the modes that are active, for example
     * `"timeline"`.
     */
