/**
 * The view of the current round.
 *
 * WHY there is no reveal variant: the question phase, the drawing phase and
 * the scoring phase carry no identity of the song, and the type says so.
 * The reveal has its own type, `PhomuRevealView`.
 */
sealed class PhomuRoundView {
    
    /**
     * A card is being drawn.
     */
    data class Drawing(
        /**
         * The number of the round.
         */
        val `roundNumber`: kotlin.UInt, 
        /**
         * The identifier of the mode of the round.
         */
        val `mode`: kotlin.String, 
        /**
         * Whether the drawing happens automatically.
         */
        val `autoDraw`: kotlin.Boolean) : PhomuRoundView() {
        companion object
    }
    
    /**
     * The question stands.
     */
    data class Question(
        /**
         * The number of the round.
         */
        val `roundNumber`: kotlin.UInt, 
        /**
         * The identifier of the mode of the round.
         */
        val `mode`: kotlin.String, 
        /**
         * The censored hints of the song.
         */
        val `hints`: List<kotlin.String>, 
        /**
         * The options the mode offers.
         */
        val `options`: List<kotlin.String>, 
        /**
         * The number of points the round is worth.
         */
        val `pointsPossible`: kotlin.UInt, 
        /**
         * Whether the answers are already locked in.
         */
        val `answersLocked`: kotlin.Boolean) : PhomuRoundView() {
        companion object
    }
    
    /**
     * The round is scored.
     */
    data class Scoring(
        /**
         * The number of the round.
         */
        val `roundNumber`: kotlin.UInt, 
        /**
         * The identifier of the mode of the round.
         */
        val `mode`: kotlin.String, 
        /**
         * The winner, if the ending condition named one.
         */
        val `winnerId`: kotlin.String?) : PhomuRoundView() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypePhomuRoundView : FfiConverterRustBuffer<PhomuRoundView>{
    override fun read(buf: ByteBuffer): PhomuRoundView {
        return when(buf.getInt()) {
            1 -> PhomuRoundView.Drawing(
                FfiConverterUInt.read(buf),
                FfiConverterString.read(buf),
                FfiConverterBoolean.read(buf),
                )
            2 -> PhomuRoundView.Question(
                FfiConverterUInt.read(buf),
                FfiConverterString.read(buf),
                FfiConverterSequenceString.read(buf),
                FfiConverterSequenceString.read(buf),
                FfiConverterUInt.read(buf),
                FfiConverterBoolean.read(buf),
                )
            3 -> PhomuRoundView.Scoring(
                FfiConverterUInt.read(buf),
                FfiConverterString.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: PhomuRoundView) = when(value) {
        is PhomuRoundView.Drawing -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.`roundNumber`)
                + FfiConverterString.allocationSize(value.`mode`)
                + FfiConverterBoolean.allocationSize(value.`autoDraw`)
            )
        }
        is PhomuRoundView.Question -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.`roundNumber`)
                + FfiConverterString.allocationSize(value.`mode`)
                + FfiConverterSequenceString.allocationSize(value.`hints`)
                + FfiConverterSequenceString.allocationSize(value.`options`)
                + FfiConverterUInt.allocationSize(value.`pointsPossible`)
                + FfiConverterBoolean.allocationSize(value.`answersLocked`)
            )
        }
        is PhomuRoundView.Scoring -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.`roundNumber`)
                + FfiConverterString.allocationSize(value.`mode`)
                + FfiConverterOptionalString.allocationSize(value.`winnerId`)
            )
        }
    }

    override fun write(value: PhomuRoundView, buf: ByteBuffer) {
        when(value) {
            is PhomuRoundView.Drawing -> {
                buf.putInt(1)
                FfiConverterUInt.write(value.`roundNumber`, buf)
                FfiConverterString.write(value.`mode`, buf)
                FfiConverterBoolean.write(value.`autoDraw`, buf)
                Unit
            }
            is PhomuRoundView.Question -> {
                buf.putInt(2)
                FfiConverterUInt.write(value.`roundNumber`, buf)
                FfiConverterString.write(value.`mode`, buf)
                FfiConverterSequenceString.write(value.`hints`, buf)
                FfiConverterSequenceString.write(value.`options`, buf)
                FfiConverterUInt.write(value.`pointsPossible`, buf)
                FfiConverterBoolean.write(value.`answersLocked`, buf)
                Unit
            }
            is PhomuRoundView.Scoring -> {
                buf.putInt(3)
                FfiConverterUInt.write(value.`roundNumber`, buf)
                FfiConverterString.write(value.`mode`, buf)
                FfiConverterOptionalString.write(value.`winnerId`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






